from abc import ABC, abstractmethod


class Vehicle(ABC):
    def __init__(self, name):
        self.name = name

    @property
    @abstractmethod
    def wheels(self):
        pass


class Bike(Vehicle):
    @property
    def wheels(self):
        return 2


b = Bike("scooter")
print(b.name, b.wheels)

