from abc import ABC, abstractmethod

PI = 3.1416


class Shape(ABC):
    @abstractmethod
    def area(self):
        pass


class Circle(Shape):
    def __init__(self, r):
        self.r = r

    def area(self):
        return PI * self.r ** 2


class Rectangle(Shape):
    def __init__(self, w, h):
        self.w = w
        self.h = h

    def area(self):
        return self.w * self.h


c = Circle(2)
r = Rectangle(3, 4)
print("Circle area:", c.area())
print("Rectangle area:", r.area())

try:
    s = Shape()
    print("Shape created")
except TypeError:
    print("TypeError raised")
